head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p.data > M > get]<br/>여러 개의 DataList 또는 DataMap 의 데이터를 지정한 유형으로 반환합니다.",
    "validation" : [
        "type(필수) 파라미터로 반환 데이터의 유형을 'JSON', 'XML', 'ARRAY' 중 하나로 설정할 수 있어야 합니다.",
        "type 이 'JSON' 인 경우 JSON 객체로 데이터를 반환해야 합니다.",
        "type 이 'ARRAY' 인 경우 Array 형식의 객체로 데이터를 반환해야 합니다.",
        "type 이 'XML' 인 경우 XML Document 로 데이터를 반환해야 합니다.",
        "type 파라미터 값은 대소문자를 구분하지 않아야 합니다.",
        "options(필수) 파라미터로 데이터를 반환할 DataList 또는 DataMap 의 정보를 ID 배열 또는 JSON 객체 배열로 설정할 수 있어야 합니다.",
        "options 파라미터를 설정하지 않으면 화면에 정의된 전체 DataList, DataMap 의 데이터를 반환해야 합니다.",
        "options 배열의 항목을 JSON 문자열로 전달하면 JSON 객체로 파싱하여 처리해야 합니다.",
        "options.id(필수) 로 데이터를 반환할 DataList 또는 DataMap 의 ID 를 설정할 수 있어야 합니다.",
        "options.key(선택) 로 반환되는 데이터에서 DataList 또는 DataMap 의 ID 값 대신 설정될 값을 설정할 수 있어야 합니다.",
        "options.key(선택) 를 생략하면 options.id 값이 키로 사용되어야 합니다.",
        "options.action(선택) 으로 반환되는 데이터에 적용될 필터를 설정할 수 있어야 합니다.",
        "options.action(선택) 을 생략하면 기본값 'all' 로 동작하여 전체 데이터를 반환해야 합니다.",
        "options.action 이 'all' 인 경우 전체 데이터를 반환해야 합니다.",
        "options.action 이 'modified' 인 경우 변경된 데이터(삽입, 삭제, 수정 포함)를 반환해야 합니다.",
        "options.action 이 'inserted' 인 경우 삽입된 데이터를 반환해야 합니다.",
        "options.action 이 'deleted' 인 경우 삭제된 데이터를 반환해야 합니다.",
        "options.action 이 'updated' 인 경우 수정된 데이터를 반환해야 합니다.",
        "options.action 이 'matched' 인 경우 options.matchedColumn 의 값이 options.matchedData 와 일치하는 데이터를 반환해야 합니다.",
        "options.action 이 'unmatched' 인 경우 options.matchedColumn 의 값이 options.matchedData 와 일치하지 않는 데이터를 반환해야 합니다.",
        "options.matchedColumn(선택) 으로 options.action 이 'matched', 'unmatched' 일 때 비교 대상 Column 의 ID 를 설정할 수 있어야 합니다.",
        "options.matchedData(선택) 로 options.action 이 'matched', 'unmatched' 일 때 비교 대상 값을 설정할 수 있어야 합니다.",
        "options.includeColumns(선택) 로 반환 받을 데이터의 Column ID 값을 배열로 설정할 수 있어야 합니다.",
        "returnOptions(선택) 로 반환 받을 데이터의 추가 옵션을 JSON 객체로 설정할 수 있어야 합니다.",
        "returnOptions.singleMode(선택) 가 true 이고 반환 객체가 1 개일 때 ID 를 제외하고 데이터만 반환해야 합니다.",
        "returnOptions.singleMode(선택) 가 false 이거나 생략(기본값 false) 되면 ID 를 포함하여 데이터를 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
    scwin.resetData();
};

// 케이스 실행 전 데이터 초기화 (rowStatus 'R' 상태)
scwin.resetData = function () {
    dlt_exam.removeAll();
    dlt_exam.insertRow(0); dlt_exam.setCellData(0, "code", "C0001"); dlt_exam.setCellData(0, "label", "TYPE1"); dlt_exam.setCellData(0, "grade", "A");
    dlt_exam.insertRow(1); dlt_exam.setCellData(1, "code", "C0002"); dlt_exam.setCellData(1, "label", "TYPE2"); dlt_exam.setCellData(1, "grade", "B");
    dlt_exam.insertRow(2); dlt_exam.setCellData(2, "code", "C0003"); dlt_exam.setCellData(2, "label", "TYPE3"); dlt_exam.setCellData(2, "grade", "A");
    dlt_exam.reform();

    dma_exam.set("lang", "lang01");
    dma_exam.set("output", "javascript");
    dma_exam.reform();
};

// 변경 상태(insert/update/delete) 데이터 만들기
scwin.makeModified = function () {
    scwin.resetData();
    // updated : row 1 의 label 변경
    dlt_exam.setCellData(1, "label", "TYPE2-M");
    // deleted : row 0 삭제
    dlt_exam.deleteRow(0);
    // inserted : 신규 row 추가
    var newIdx = dlt_exam.insertRow();
    dlt_exam.setCellData(newIdx, "code", "C0004");
    dlt_exam.setCellData(newIdx, "label", "TYPE4");
    dlt_exam.setCellData(newIdx, "grade", "C");
};



scwin.put = function (msg) {
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};

scwin.verify = function (label, actual, expected) {
    var pass = (String(actual) === String(expected));
    scwin.put("    [" + (pass ? "✓ PASS" : "✗ FAIL") + "] " + label + " = '" + actual + "'" + (pass ? "" : " (기대: '" + expected + "')"));
    return pass;
};

scwin.printResult = function (title, ok) {
    scwin.put(ok ? "결과 : " + title + " 정상 동작 확인" : "결과 : " + title + " 검증 불일치");
    scwin.put("");
};



scwin.btn_get_onclick = function () {
    var s = par_scenario.getValue();

    if (s === "1") {
        scwin.resetData();
        scwin.put("══ 시나리오 1 : type='JSON' + 단건(DataMap, ID 배열) ══");
        var ret = $p.data.get("JSON", ["dma_exam"]);
        var p1 = scwin.verify("typeof ret", typeof ret, "object");
        var p2 = scwin.verify("ret.dma_exam.lang", ret.dma_exam.lang, "lang01");
        var p3 = scwin.verify("ret.dma_exam.output", ret.dma_exam.output, "javascript");
        scwin.printResult("type='JSON' + ID 배열(단건)", p1 && p2 && p3);
    } else if (s === "2") {
        scwin.resetData();
        scwin.put("══ 시나리오 2 : type='JSON' + 다건(DataList+DataMap) ══");
        var ret = $p.data.get("JSON", ["dma_exam", "dlt_exam"]);
        var p1 = scwin.verify("ret.dma_exam.lang", ret.dma_exam.lang, "lang01");
        var p2 = scwin.verify("ret.dlt_exam.length", ret.dlt_exam.length, 3);
        var p3 = scwin.verify("ret.dlt_exam[0].code", ret.dlt_exam[0].code, "C0001");
        var p4 = scwin.verify("ret.dlt_exam[2].grade", ret.dlt_exam[2].grade, "A");
        scwin.printResult("type='JSON' + ID 배열(다건)", p1 && p2 && p3 && p4);
    } else if (s === "3") {
        scwin.resetData();
        scwin.put("══ 시나리오 3 : type='ARRAY' + 다건 ══");
        var ret = $p.data.get("ARRAY", ["dma_exam", "dlt_exam"]);
        var p1 = scwin.verify("typeof ret", typeof ret, "object");
        var p2 = scwin.verify("ret.dlt_exam.columnInfo[0]", ret.dlt_exam.columnInfo[0], "code");
        var p3 = scwin.verify("ret.dlt_exam.columnInfo.length", ret.dlt_exam.columnInfo.length, 3);
        var p4 = scwin.verify("ret.dlt_exam.data[0] (첫 행 첫 컬럼)", ret.dlt_exam.data[0], "C0001");
        var p5 = scwin.verify("ret.dma_exam.lang", ret.dma_exam.lang, "lang01");
        scwin.printResult("type='ARRAY' + 다건", p1 && p2 && p3 && p4 && p5);
    } else if (s === "4") {
        scwin.resetData();
        scwin.put("══ 시나리오 4 : type='XML' + 다건 ══");
        var ret = $p.data.get("XML", ["dma_exam", "dlt_exam"]);
        // XMLDocument 또는 Document 형식 검증
        var isXmlDoc = (ret && (ret.nodeType === 9 || (ret.documentElement && ret.documentElement.nodeName)));
        var p1 = scwin.verify("XML Document 반환 여부", isXmlDoc ? "true" : "false", "true");
        var rootName = ret.documentElement ? ret.documentElement.nodeName : "";
        var p2 = scwin.verify("ret.documentElement.nodeName", rootName, "map");
        // dlt_exam 노드 존재 검증
        var lists = ret.getElementsByTagName("list");
        var hasDlt = false;
        for (var i = 0; i < lists.length; i++) {
            if (lists[i].getAttribute("id") === "dlt_exam") { hasDlt = true; break; }
        }
        var p3 = scwin.verify("dlt_exam list 노드 존재", hasDlt ? "true" : "false", "true");
        scwin.printResult("type='XML' + 다건", p1 && p2 && p3);
    } else if (s === "5") {
        scwin.resetData();
        scwin.put("══ 시나리오 5 : options 생략 (화면 전체 DataList/DataMap 반환) ══");
        var ret = $p.data.get("JSON");
        var p1 = scwin.verify("ret.dma_exam 존재", ret.dma_exam ? "true" : "false", "true");
        var p2 = scwin.verify("ret.dlt_exam 존재", ret.dlt_exam ? "true" : "false", "true");
        var p3 = scwin.verify("ret.dlt_exam.length", ret.dlt_exam.length, 3);
        scwin.printResult("options 생략 (전체 반환)", p1 && p2 && p3);
    } else if (s === "6") {
        scwin.resetData();
        scwin.put("══ 시나리오 6 : options.key 로 ID 별칭 지정 ══");
        var ret = $p.data.get("JSON", [{ "id" : "dma_exam", "key" : "dma_alias" }]);
        var p1 = scwin.verify("ret.dma_alias 존재", ret.dma_alias ? "true" : "false", "true");
        var p2 = scwin.verify("ret.dma_exam 미존재(원래 ID)", ret.dma_exam ? "true" : "false", "false");
        var p3 = scwin.verify("ret.dma_alias.lang", ret.dma_alias.lang, "lang01");
        scwin.printResult("options.key (ID 별칭)", p1 && p2 && p3);
    } else if (s === "7") {
        scwin.resetData();
        scwin.put("══ 시나리오 7 : options.action='all' (전체 반환, 기본값과 동일) ══");
        var ret = $p.data.get("JSON", [{ "id" : "dlt_exam", "action" : "all" }]);
        var p1 = scwin.verify("ret.dlt_exam.length", ret.dlt_exam.length, 3);
        // 비교 : action 생략 시도 동일하게 동작
        var ret2 = $p.data.get("JSON", [{ "id" : "dlt_exam" }]);
        var p2 = scwin.verify("action 생략 시 length (기본값 'all')", ret2.dlt_exam.length, 3);
        scwin.printResult("action='all' (기본값 동작 포함)", p1 && p2);
    } else if (s === "8") {
        scwin.makeModified();
        scwin.put("══ 시나리오 8 : options.action='modified' (변경 데이터 전체) ══");
        var ret = $p.data.get("JSON", [{ "id" : "dlt_exam", "action" : "modified" }]);
        var p1 = scwin.verify("ret.dlt_exam.length (insert+delete+update = 3)", ret.dlt_exam.length, 3);
        // rowStatus 종류 확인
        var statusSet = {};
        for (var i = 0; i < ret.dlt_exam.length; i++) {
            statusSet[ret.dlt_exam[i].rowStatus] = true;
        }
        var p2 = scwin.verify("rowStatus 'C'(삽입) 포함", statusSet["C"] ? "true" : "false", "true");
        var p3 = scwin.verify("rowStatus 'U'(수정) 포함", statusSet["U"] ? "true" : "false", "true");
        var p4 = scwin.verify("rowStatus 'D'(삭제) 포함", statusSet["D"] ? "true" : "false", "true");
        scwin.printResult("action='modified'", p1 && p2 && p3 && p4);
    } else if (s === "9") {
        scwin.makeModified();
        scwin.put("══ 시나리오 9 : options.action='inserted' (삽입 데이터만) ══");
        var ret = $p.data.get("JSON", [{ "id" : "dlt_exam", "action" : "inserted" }]);
        var p1 = scwin.verify("ret.dlt_exam.length", ret.dlt_exam.length, 1);
        var p2 = scwin.verify("ret.dlt_exam[0].code", ret.dlt_exam[0].code, "C0004");
        var p3 = scwin.verify("ret.dlt_exam[0].rowStatus", ret.dlt_exam[0].rowStatus, "C");
        scwin.printResult("action='inserted'", p1 && p2 && p3);
    } else if (s === "10") {
        scwin.makeModified();
        scwin.put("══ 시나리오 10 : options.action='deleted' (삭제 데이터만) ══");
        var ret = $p.data.get("JSON", [{ "id" : "dlt_exam", "action" : "deleted" }]);
        var p1 = scwin.verify("ret.dlt_exam.length", ret.dlt_exam.length, 1);
        var p2 = scwin.verify("ret.dlt_exam[0].code", ret.dlt_exam[0].code, "C0001");
        var p3 = scwin.verify("ret.dlt_exam[0].rowStatus", ret.dlt_exam[0].rowStatus, "D");
        scwin.printResult("action='deleted'", p1 && p2 && p3);
    } else if (s === "11") {
        scwin.makeModified();
        scwin.put("══ 시나리오 11 : options.action='updated' (수정 데이터만) ══");
        var ret = $p.data.get("JSON", [{ "id" : "dlt_exam", "action" : "updated" }]);
        var p1 = scwin.verify("ret.dlt_exam.length", ret.dlt_exam.length, 1);
        var p2 = scwin.verify("ret.dlt_exam[0].code", ret.dlt_exam[0].code, "C0002");
        var p3 = scwin.verify("ret.dlt_exam[0].label (수정값)", ret.dlt_exam[0].label, "TYPE2-M");
        var p4 = scwin.verify("ret.dlt_exam[0].rowStatus", ret.dlt_exam[0].rowStatus, "U");
        scwin.printResult("action='updated'", p1 && p2 && p3 && p4);
    } else if (s === "12") {
        scwin.resetData();
        scwin.put("══ 시나리오 12 : options.action='matched' + matchedColumn/matchedData ══");
        var ret = $p.data.get("JSON", [{
            "id" : "dlt_exam",
            "action" : "matched",
            "matchedColumn" : "grade",
            "matchedData" : "A"
        }]);
        var p1 = scwin.verify("ret.dlt_exam.length (grade='A' 행 수)", ret.dlt_exam.length, 2);
        var p2 = scwin.verify("ret.dlt_exam[0].grade", ret.dlt_exam[0].grade, "A");
        var p3 = scwin.verify("ret.dlt_exam[1].grade", ret.dlt_exam[1].grade, "A");
        scwin.printResult("action='matched' + matchedColumn/matchedData", p1 && p2 && p3);
    } else if (s === "13") {
        scwin.resetData();
        scwin.put("══ 시나리오 13 : options.action='unmatched' + matchedColumn/matchedData ══");
        var ret = $p.data.get("JSON", [{
            "id" : "dlt_exam",
            "action" : "unmatched",
            "matchedColumn" : "grade",
            "matchedData" : "A"
        }]);
        var p1 = scwin.verify("ret.dlt_exam.length (grade!='A' 행 수)", ret.dlt_exam.length, 1);
        var p2 = scwin.verify("ret.dlt_exam[0].grade", ret.dlt_exam[0].grade, "B");
        var p3 = scwin.verify("ret.dlt_exam[0].code", ret.dlt_exam[0].code, "C0002");
        scwin.printResult("action='unmatched' + matchedColumn/matchedData", p1 && p2 && p3);
    } else if (s === "14") {
        scwin.resetData();
        scwin.put("══ 시나리오 14 : options.includeColumns 로 특정 Column 만 반환 ══");
        var ret = $p.data.get("JSON", [{ "id" : "dlt_exam", "includeColumns" : ["code", "grade"] }]);
        var p1 = scwin.verify("ret.dlt_exam[0].code", ret.dlt_exam[0].code, "C0001");
        var p2 = scwin.verify("ret.dlt_exam[0].grade", ret.dlt_exam[0].grade, "A");
        var p3 = scwin.verify("ret.dlt_exam[0].label 미포함", (ret.dlt_exam[0].label === undefined) ? "true" : "false", "true");
        scwin.printResult("includeColumns", p1 && p2 && p3);
    } else if (s === "15") {
        scwin.resetData();
        scwin.put("══ 시나리오 15 : returnOptions.singleMode=true (단건 → ID 제외) ══");
        var ret = $p.data.get("JSON", ["dma_exam"], { "singleMode" : true });
        var p1 = scwin.verify("ret.dma_exam 미존재(ID 제외)", ret.dma_exam ? "true" : "false", "false");
        var p2 = scwin.verify("ret.lang (데이터 직접 반환)", ret.lang, "lang01");
        var p3 = scwin.verify("ret.output", ret.output, "javascript");
        scwin.printResult("returnOptions.singleMode=true", p1 && p2 && p3);
    } else if (s === "16") {
        scwin.resetData();
        scwin.put("══ 시나리오 16 : returnOptions.singleMode=false (기본값, ID 포함) ══");
        var ret = $p.data.get("JSON", ["dma_exam"], { "singleMode" : false });
        var p1 = scwin.verify("ret.dma_exam 존재(ID 포함)", ret.dma_exam ? "true" : "false", "true");
        var p2 = scwin.verify("ret.dma_exam.lang", ret.dma_exam.lang, "lang01");
        // 기본값 동작 (returnOptions 자체 생략)
        var ret2 = $p.data.get("JSON", ["dma_exam"]);
        var p3 = scwin.verify("returnOptions 생략 시 ret2.dma_exam 존재(기본값 false)", ret2.dma_exam ? "true" : "false", "true");
        scwin.printResult("returnOptions.singleMode=false (기본값 동작)", p1 && p2 && p3);
    } else if (s === "17") {
        scwin.resetData();
        scwin.put("══ 시나리오 17 : type 파라미터 대소문자 구분 안 함 ('json' 소문자) ══");
        var ret = $p.data.get("json", ["dma_exam"]);
        var p1 = scwin.verify("typeof ret", typeof ret, "object");
        var p2 = scwin.verify("ret.dma_exam.lang", ret.dma_exam.lang, "lang01");
        // 추가 : 'Json' 혼합
        var ret2 = $p.data.get("Json", ["dma_exam"]);
        var p3 = scwin.verify("'Json' 도 동일 결과", ret2.dma_exam.lang, "lang01");
        scwin.printResult("type 대소문자 무시", p1 && p2 && p3);
    } else if (s === "18") {
        scwin.resetData();
        scwin.put("══ 시나리오 18 : options 항목을 JSON 문자열로 전달 (파싱) ══");
        var ret = $p.data.get("JSON", ['{"id":"dma_exam","key":"dma_str_key"}']);
        var p1 = scwin.verify("ret.dma_str_key 존재 (문자열 → JSON 파싱 + key 적용)", ret.dma_str_key ? "true" : "false", "true");
        var p2 = scwin.verify("ret.dma_str_key.lang", ret.dma_str_key.lang, "lang01");
        var p3 = scwin.verify("ret.dma_exam 미존재(원래 ID)", ret.dma_exam ? "true" : "false", "false");
        scwin.printResult("options 항목 JSON 문자열 파싱", p1 && p2 && p3);
    }
};
